from collections import defaultdict
from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # Map customer -> list of tuples: (available_date, points_earned)
        self._earnings: dict[str, list[tuple[date, int]]] = defaultdict(list)
        # Map customer -> total points redeemed so far
        self._redeemed: dict[str, int] = defaultdict(int)

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        points = int(amount // 10)
        if points > 0:
            available_day = day + timedelta(days=14)
            self._earnings[customer].append((available_day, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        total_matured = sum(
            pts for avail_day, pts in self._earnings[customer] if avail_day <= day
        )
        return total_matured - self._redeemed[customer]

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points for a customer on the given day."""
        if points <= 0 or points % 100 != 0:
            raise ValueError("Points can be redeemed only in positive multiples of 100.")

        available = self.balance(customer, day)
        if points > available:
            raise ValueError(
                f"Cannot redeem {points} points; only {available} points available."
            )

        self._redeemed[customer] += points
